face.layout_source:
// robotizer.face: the panel for tap/examples/spectral/robotizer.tap.
//
// Only layout lives here.  The style is a theme from face/themes, chosen per
// family in face/themes/families.json:
//
//   facec face/themes/<theme>.face tap/examples/spectral/robotizer.face --meta <graph>.cragmeta

face "Robotizer" {
  row(gap = 10) {
    box "Voice" { selector "Voice" (voice) knob.big "Mix" (mix) }
    viz(grow = 1)
  }
}
